      --bg: #0b1020;
      --panel: rgba(18, 25, 46, 0.86);
      --panel-strong: #161f38;
      --text: #f6f8ff;
      --muted: #9aa8c7;
      --accent: #8b5cf6;
      --accent-2: #22d3ee;
      --border: rgba(154, 168, 199, 0.22);
      --shadow: rgba(0, 0, 0, 0.42);
    }

