      margin: 0 0 22px;
      padding: 22px;
      border: 1px solid var(--border);
      border-radius: 22px;
      background: linear-gradient(180deg, rgba(255, 255, 255, 0.055), rgba(255, 255, 255, 0.025));
    }

    .question-title {
      display: flex;
      gap: 12px;
      align-items: flex-start;
      margin: 0 0 8px;
      font-size: 1.08rem;
      font-weight: 800;
      line-height: 1.35;
    }

    .question-number {
      display: inline-grid;
      flex: 0 0 30px;
      width: 30px;
      height: 30px;
      place-items: center;
      border-radius: 999px;
      background: linear-gradient(135deg, var(--accent), var(--accent-2));
      color: #070b16;
      font-size: 0.85rem;
      font-weight: 900;
