</head>
<body>
  <main id="root" class="quiz-app"></main>

  <script>
    const quizQuestions = [
      {
        prompt: "Which of these are commonly used programming languages?",
        helpText: "Select every option that is a programming language. There may be more than one correct answer.",
        choices: ["Python", "JavaScript", "HTML", "C++"]
      },
      {
        prompt: "Which languages are often used for systems programming?",
        choices: ["Rust", "Go", "Swift", "C"]
      },
      {
        prompt: "Which languages are primarily associated with web development?",
        choices: ["TypeScript", "PHP", "Ruby", "SQL"]
      }
    ];

    function Choice({ questionIndex, choiceIndex, label }) {
      const id = `question-${questionIndex + 1}-choice-${choiceIndex + 1}`;

      return `
        <label class="choice" for="${id}">
          <input
            type="checkbox"
            id="${id}"
            name="question-${questionIndex + 1}"
            value="${label}"
          >
          <span>${label}</span>
        </label>
      `;
    }

    function QuestionField({ question, questionIndex }) {
      return `
        <div class="form-field">
          <p class="question-title">
            <span class="question-number">${questionIndex + 1}</span>
            <span>${question.prompt}</span>
          </p>
          ${question.helpText ? `<p class="help-text">${question.helpText}</p>` : ""}
          <div class="choices">
            ${question.choices.map((choice, choiceIndex) => Choice({ questionIndex, choiceIndex, label: choice })).join("")}
          </div>
        </div>
      `;
    }

    function QuizApp({ questions }) {
      return `
        <section class="quiz-card" aria-labelledby="quiz-title">
          <header class="quiz-header">
            <p class="eyebrow">Multi-select quiz</p>
            <h1 id="quiz-title">Computer Languages</h1>
            <p class="intro">
              Test your knowledge of computer languages. Each question supports multiple selections.
            </p>
          </header>
          <form id="quiz-form">
            ${questions.map((question, questionIndex) => QuestionField({ question, questionIndex })).join("")}
            <div class="actions">
              <button type="submit">Submit answers</button>
              <p id="result" class="result" aria-live="polite"></p>
            </div>
          </form>
        </section>
      `;
    }

    document.getElementById("root").innerHTML = QuizApp({ questions: quizQuestions });

    document.getElementById("quiz-form").addEventListener("submit", (event) => {
      event.preventDefault();

      const selectedCount = document.querySelectorAll('input[type="checkbox"]:checked').length;
      const message = selectedCount === 1
        ? "You selected 1 answer."
        : `You selected ${selectedCount} answers.`;

      document.getElementById("result").textContent = message;
    });
  </script>
</body>
</html>
