const script = html.match(/<script>([\s\S]*)<\/script>/)[1];
const root = { innerHTML: '' };
const form = { addEventListener() {} };
global.document = {
  getElementById(id) {
    if (id === 'root') return root;
    if (id === 'quiz-form') return form;
    if (id === 'result') return { textContent: '' };
    return null;
  },
  querySelectorAll() { return []; }
};
eval(script);
console.log('rendered form-field count:', (root.innerHTML.match(/class="form-field"/g) || []).length);
console.log('rendered checkbox count:', (root.innerHTML.match(/type="checkbox"/g) || []).length);
console.log('rendered submit count:', (root.innerHTML.match(/type="submit"/g) || []).length);
